CREATE OR REPLACE FUNCTION public.sync_deactivated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.active = true then
    new.deactivated_at := null;
  elsif new.active = false and old.active is distinct from false then
    new.deactivated_at := now();
  end if;

  return new;
end;
